const { spawn } = require('child_process');
const http = require('http');
const fs = require('fs');
const path = require('path');
const assert = require('assert/strict');

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
const root = path.resolve(__dirname, 'stats-bugs-dist-current');
const evidence = path.resolve(__dirname, '../../EVIDENCIAS_BUGS_STATS');
fs.mkdirSync(evidence, { recursive: true });

const server = http.createServer((request, response) => {
  const file = path.join(root, request.url === '/' ? 'index.html' : decodeURIComponent(request.url));
  if (!file.startsWith(root) || !fs.existsSync(file)) {
    response.writeHead(404);
    response.end();
    return;
  }
  response.setHeader('Content-Type', file.endsWith('.js') ? 'application/javascript' : file.endsWith('.html') ? 'text/html' : 'application/octet-stream');
  response.end(fs.readFileSync(file));
});

const browser = spawn(process.env.UI_BROWSER || 'C:/Program Files (x86)/Microsoft/Edge/Application/msedge.exe', [
  '--headless=new', '--disable-gpu', '--no-first-run', '--remote-debugging-port=9340',
  `--user-data-dir=${path.join(__dirname, 'stats-evidence-browser')}`, 'about:blank',
], { windowsHide: true, stdio: 'ignore' });

let socket;
(async () => {
  await new Promise((resolve) => server.listen(8090, '127.0.0.1', resolve));
  let tabs;
  for (let attempt = 0; attempt < 40; attempt += 1) {
    try {
      tabs = await (await fetch('http://127.0.0.1:9340/json')).json();
      break;
    } catch {
      await sleep(250);
    }
  }
  assert(tabs);
  socket = new WebSocket(tabs.find((tab) => tab.type === 'page').webSocketDebuggerUrl);
  await new Promise((resolve) => socket.addEventListener('open', resolve, { once: true }));
  let id = 0;
  const pending = new Map();
  const call = (method, params = {}) => new Promise((resolve, reject) => {
    const requestId = ++id;
    pending.set(requestId, { resolve, reject });
    socket.send(JSON.stringify({ id: requestId, method, params }));
  });

  const dives = [
    { id: 1, country: 'EspaÃ±a', location: 'Cala CalÃ³', date: '2024-08-30T10:00:00Z', maxDepth: 15, duration: 50 },
    { id: 2, country: 'Andorra', location: 'Balicasag Island', date: '2024-07-20T10:00:00Z', maxDepth: 30, duration: 45 },
    { id: 3, country: 'Portugal', location: 'Berlengas', date: '2024-06-14T10:00:00Z', maxDepth: 22, duration: 70 },
    { id: 4, country: 'EspaÃ±a', location: 'Cabo de Gata', date: '2024-05-18T10:00:00Z', maxDepth: 41, duration: 35 },
    { id: 5, country: 'Francia', location: 'Marseille', date: '2024-04-11T10:00:00Z', maxDepth: 18, duration: 80 },
    { id: 6, country: 'MÃ©xico', location: 'Cozumel', date: '2024-03-04T10:00:00Z', maxDepth: 28, duration: 55 },
    { id: 7, country: 'Italia', location: 'Ustica', date: '2024-02-12T10:00:00Z', maxDepth: 24, duration: 65 },
    { id: 8, country: 'EspaÃ±a', location: 'Lanzarote', date: '2024-01-10T10:00:00Z', maxDepth: 32, duration: 42 },
  ];

  socket.addEventListener('message', async (event) => {
    const message = JSON.parse(event.data);
    if (message.id) {
      const entry = pending.get(message.id);
      pending.delete(message.id);
      if (entry) message.error ? entry.reject(message.error) : entry.resolve(message.result);
    }
    if (message.method === 'Fetch.requestPaused') {
      const request = message.params.request;
      const url = new URL(request.url);
      const data = url.pathname === '/auth/login'
        ? { accessToken: `x.${Buffer.from('{"userId":1}').toString('base64url')}.x` }
        : url.pathname === '/dives/my' ? dives : [];
      await call('Fetch.fulfillRequest', {
        requestId: message.params.requestId,
        responseCode: 200,
        responseHeaders: [
          { name: 'Content-Type', value: 'application/json' },
          { name: 'Access-Control-Allow-Origin', value: '*' },
          { name: 'Access-Control-Allow-Headers', value: '*' },
        ],
        body: Buffer.from(JSON.stringify(data)).toString('base64'),
      });
    }
  });

  await call('Page.enable');
  await call('Runtime.enable');
  await call('Fetch.enable', { patterns: [{ urlPattern: 'http://localhost:3000/*' }] });
  const evaluate = async (expression) => {
    const result = await call('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
    if (result.exceptionDetails) throw new Error(JSON.stringify(result.exceptionDetails));
    return result.result.value;
  };
  const resize = async (width, height) => {
    await call('Emulation.setDeviceMetricsOverride', { width, height, deviceScaleFactor: 1, mobile: false });
    await sleep(350);
  };
  const screenshot = async (name) => {
    const result = await call('Page.captureScreenshot');
    fs.writeFileSync(path.join(evidence, name), Buffer.from(result.data, 'base64'));
  };
  const clickText = async (text) => {
    const clicked = await evaluate(`(() => { const node = [...document.querySelectorAll('button')].find((item) => item.textContent.trim() === ${JSON.stringify(text)}); if (!node) return false; node.click(); return true; })()`);
    assert(clicked, `Missing button: ${text}`);
    await sleep(500);
  };

  await resize(1440, 900);
  await call('Page.navigate', { url: 'http://127.0.0.1:8090' });
  await sleep(1200);
  await clickText('Log In');
  await sleep(500);
  await clickText('View dive statistics');
  await sleep(900);
  await screenshot('stats-desktop.png');
  const desktopMetrics = await evaluate(`(() => ({ bodyWidth: document.body.scrollWidth, viewport: innerWidth, summary: document.querySelector('[class*="css-"]')?.getBoundingClientRect?.().width || 0, highlights: [...document.querySelectorAll('div')].filter((e) => e.textContent.includes('HIGHLIGHTS')).length }))()`);
  await resize(390, 844);
  await screenshot('stats-mobile-overflow.png');
  const mobileMetrics = await evaluate(`(() => ({ bodyWidth: document.body.scrollWidth, viewport: innerWidth, horizontalOverflow: document.documentElement.scrollWidth > innerWidth, clippedLabels: [...document.querySelectorAll('div')].filter((e) => e.textContent.includes('Highlights')).length }))()`);
  await evaluate(`(() => { const buttons = [...document.querySelectorAll('button')]; const item = buttons.find((node) => node.textContent.includes('Last year')); if (item) item.click(); })()`);
  await sleep(300);
  await screenshot('stats-filter-state.png');
  fs.writeFileSync(path.join(evidence, 'measurements.json'), JSON.stringify({ desktop: desktopMetrics, mobile: mobileMetrics }, null, 2));
  console.log(JSON.stringify({ desktop: desktopMetrics, mobile: mobileMetrics }));
})().catch((error) => {
  console.error(error);
  process.exitCode = 1;
}).finally(() => {
  socket?.close();
  browser.kill();
  server.close();
});
